"""Bounded acoustic segmentation; requires ffmpeg, NumPy and SciPy offline only."""
from pathlib import Path
import subprocess,json,numpy as np
from scipy.signal import welch,find_peaks,correlate
p=Path(__file__).parent;sr=24000
raw=subprocess.check_output(['ffmpeg','-v','error','-i',str(p/'ryton-fissore-magnum_revving.mp3'),'-f','f32le','-ac','1','-ar',str(sr),'-'])
x=np.frombuffer(raw,'<f4').astype(float);rows=[]
for start in np.arange(0,len(x)/sr-.25,.1):
 z=x[round(start*sr):round((start+.25)*sr)];f,P=welch(z,sr,nperseg=4096);power=P.sum()+1e-20;rms=np.sqrt(np.mean(z*z));centroid=(f*P).sum()/power
 a=correlate(z-z.mean(),z-z.mean(),mode='full',method='fft')[len(z)-1:];lo,hi=round(sr/250),round(sr/20);lag=lo+np.argmax(a[lo:hi]);periodicity=a[lag]/max(a[0],1e-20)
 rows.append({'time':round(float(start+.125),3),'rms':float(rms),'centroidHz':float(centroid),'bassFraction':float(P[f<150].sum()/power),'periodicity':float(periodicity),'periodHz':float(sr/lag)})
F=np.array([[np.log(r['rms']+1e-8),np.log(r['centroidHz']+1),r['bassFraction'],r['periodicity']] for r in rows]);scale=np.maximum(np.std(F,axis=0),.02);nov=np.zeros(len(rows))
for i in range(3,len(rows)-3):nov[i]=np.linalg.norm((F[i:i+3].mean(0)-F[i-3:i].mean(0))/scale)
peaks,_=find_peaks(nov,distance=8,prominence=.35);chosen=sorted(sorted(peaks,key=lambda i:nov[i],reverse=True)[:9]);bounds=[0]+[rows[i]['time'] for i in chosen]+[len(x)/sr];segments=[]
for a,b in zip(bounds,bounds[1:]):
 rr=[r for r in rows if a<=r['time']<b];level=np.mean([r['rms'] for r in rr]);change=np.log((rr[-1]['rms']+1e-8)/(rr[0]['rms']+1e-8));label='rising level' if change>.35 else 'falling level' if change<-.35 else 'relatively steady level'
 segments.append({'start':round(a,3),'end':round(b,3),'description':label,'meanRms':float(level),'meanCentroidHz':float(np.mean([r['centroidHz'] for r in rr])),'meanPeriodicity':float(np.mean([r['periodicity'] for r in rr]))})
result={'source':'ryton-fissore-magnum_revving.mp3','duration':len(x)/sr,'method':'250 ms windows / 100 ms hop; standardized log RMS, log spectral centroid, bass fraction and autocorrelation periodicity; 300 ms before/after novelty, bounded nine strongest separated peaks','limitations':'Acoustic change points only. Periodicity may represent a harmonic or interference, not crank frequency; no exact RPM, load, acceleration or engine-state labels are inferred. Mono analysis discards stereo cues. Boundaries need listening refinement.','segments':segments,'frames':rows}
(p/'rev-recording-analysis.json').write_text(json.dumps(result,indent=2)+'\n')
html='''<!doctype html><meta charset="utf-8"><title>Rev recording segment audition</title><style>body{font:16px system-ui;background:#10151c;color:#eee;max-width:950px;margin:30px auto;padding:16px}button{margin:5px;padding:9px}canvas{width:100%;height:200px;background:#202a36}small{color:#bbc}</style><h1>Rev recording: acoustic segments</h1><p>Candidate boundaries derived from acoustic changes, not verified engine states. Compare adjoining clips before deciding how to use them.</p><audio id="audio" controls src="ryton-fissore-magnum_revving.mp3"></audio><p><button id="all">Play full recording</button><button id="stop">Stop</button></p><canvas id="plot" width="900" height="200"></canvas><p id="status"></p><div id="clips"></div><small>Orange: relative RMS. Blue: relative spectral centroid. White lines: candidate boundaries. No loudness normalization is applied; retain volume when comparing. Use the original full recording to assess context.</small><script>const data=DATA,a=document.querySelector('audio'),status=document.querySelector('#status');let end=Infinity;document.querySelector('#all').onclick=()=>{end=Infinity;a.currentTime=0;a.play()};document.querySelector('#stop').onclick=()=>a.pause();data.segments.forEach((s,i)=>{let b=document.createElement('button');b.textContent=`${i+1}: ${s.start.toFixed(2)}–${s.end.toFixed(2)} s · ${s.description}`;b.onclick=async()=>{if(a.readyState<1)await new Promise(resolve=>a.addEventListener("loadedmetadata",resolve,{once:true}));end=s.end;a.currentTime=s.start;a.play();status.textContent=b.textContent};document.querySelector('#clips').append(b)});function tick(){if(a.currentTime>=end)a.pause();requestAnimationFrame(tick)}tick();const c=document.querySelector('canvas').getContext('2d'),W=900,H=200;[['rms','#ff9933'],['centroidHz','#55ccff']].forEach(([key,color])=>{let max=Math.max(...data.frames.map(r=>r[key]));c.strokeStyle=color;c.beginPath();data.frames.forEach((r,i)=>{let x=r.time/data.duration*W,y=H-r[key]/max*(H-10);i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke()});c.strokeStyle='#ddd';data.segments.forEach(s=>{let x=s.start/data.duration*W;c.beginPath();c.moveTo(x,0);c.lineTo(x,H);c.stroke()});window.analysis=data;</script>'''.replace('DATA',json.dumps(result))
(p/'rev-recording-audition.html').write_text(html)
print(json.dumps(segments,indent=2))
